const {chromium} = require('playwright');
const path = require('path');
const OUT = process.argv[2] || 'tst/shots';
require('fs').mkdirSync(OUT, {recursive: true});
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({viewport: {width: 1280, height: 940}, deviceScaleFactor: 1});
  const errs = [];
  p.on('pageerror', e => errs.push('pageerror: ' + e.message));
  p.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errs.push(m.type() + ': ' + m.text()); });
  await p.goto('http://127.0.0.1:8765/index.html');
  await p.waitForTimeout(1500);
  const ph = p.locator('#phone');
  let n = 0;
  const shot = async (name, ms = 450) => { await p.waitForTimeout(ms); await ph.screenshot({path: `${OUT}/${String(++n).padStart(2, '0')}_${name}.png`}); };
  const sim = async (k, v) => { await p.click(`#sim button[data-k="${k}"][data-v="${v}"]`); await p.waitForTimeout(200); };
  const ons = async (label) => { await p.locator('#edge-on button', {hasText: label}).first().click(); await p.waitForTimeout(250); };
  const scrollTo = async y => { await p.evaluate(y => { const s = top_().ctx.scroll; s.scrollTop = y; }, y); await p.waitForTimeout(150); };
  const act = async a => { await p.evaluate(a => act_(a, top_().ctx), a); await p.waitForTimeout(150); };
  const tapText = async t => { await p.locator('#phone').getByText(t, {exact: false}).last().click(); await p.waitForTimeout(250); };
  const S = process.argv[3] || 'all';
  const run = async (name, f) => { if (S === 'all' || S.split(',').includes(name)) { try { await f(); } catch (e) { errs.push(name + ' FAILED: ' + e.message.split('\n')[0]); } } };

  await run('home', async () => {
    await sim('user', 'new'); await sim('loc', 'off');
    await shot('home_new_top'); await scrollTo(860); await shot('home_locoff_map');
    await scrollTo(2700); await shot('home_new_fav'); await scrollTo(3650); await shot('home_new_ready');
    await ons('Location permission prompt'); await shot('home_loc_alert', 700);
    await tapText('عدم السماح'); await scrollTo(860); await shot('home_loc_denied', 500);
    await p.evaluate(() => { const b = document.querySelector('[data-a="enableLoc"]'); b.click(); }); await shot('loc_blocked_sheet', 600);
    await tapText('افتح الإعدادات'); await p.waitForTimeout(600);
    await sim('user', 'regular');
    await p.click('#c-home button:nth-child(3)'); await p.waitForTimeout(300);
    await sim('user', 'new'); await sim('loc', 'off'); await scrollTo(2650); await shot('home3_new');
    await scrollTo(900); await shot('home3_locoff');
    await sim('user', 'regular'); await sim('loc', 'on');
    await p.click('#c-home button:nth-child(2)'); await p.waitForTimeout(300);
    await sim('user', 'new'); await sim('loc', 'off'); await scrollTo(860); await shot('home2_new_loc');
    await sim('user', 'regular'); await sim('loc', 'on');
    await p.click('#c-home button:nth-child(1)'); await p.waitForTimeout(300);
    await sim('net', 'offline'); await shot('home_offline');
    await sim('net', 'slow'); await shot('home_slow', 300);
    await sim('net', 'online');
  });
  await run('search', async () => {
    await p.click('#b-reset'); await p.waitForTimeout(300);
    await act('search'); await shot('search_empty', 600);
    await p.fill('#phone input', 'قهوة'); await shot('search_qahwa', 600);
    await p.keyboard.press('Backspace'); await p.waitForTimeout(300);
    await p.fill('#phone input', 'بيتزا هت'); await shot('search_none', 600);
    await sim('net', 'offline'); await p.fill('#phone input', 'نون'); await shot('search_offline', 600);
    await sim('net', 'slow'); await p.fill('#phone input', 'كاش'); await shot('search_slow', 300); await shot('search_cash', 900);
    await sim('net', 'online');
    await p.locator('#phone .s-row').first().click(); await shot('search_to_merchant', 600);
  });
  await run('merchant', async () => {
    await p.click('#b-reset'); await p.waitForTimeout(200);
    await p.evaluate(() => { resetTo([{t: 'home'}, {t: 'merchant'}]); }); await p.waitForTimeout(300);
    await act('fav'); await shot('merchant_fav');
    await act('share'); await shot('merchant_share', 600); await tapText('إغلاق'); await p.waitForTimeout(400);
    await ons("Can't load"); await shot('merchant_error', 600);
    await sim('net', 'online'); await tapText('حاول مرة أخرى'); await shot('merchant_back', 600);
  });
  await run('offer', async () => {
    await p.evaluate(() => { resetTo([{t: 'home'}, {t: 'merchant'}, {t: 'offer', mode: 'tall', flow: 1}]); }); await p.waitForTimeout(400);
    await sim('offer', 'last'); await shot('offer_last');
    await act('scan'); await shot('offer_last_confirm', 600); await tapText('ليس الآن'); await p.waitForTimeout(400);
    await sim('offer', 'used'); await shot('offer_used');
    await sim('offer', 'expired'); await shot('offer_expired');
    await sim('offer', 'soon'); await shot('offer_soon');
    await act('remind'); await shot('offer_reminded');
    await sim('offer', 'ok'); await act('policy'); await shot('offer_policy', 600); await tapText('فهمت'); await p.waitForTimeout(400);
    await act('share'); await shot('offer_share', 600); await tapText('إغلاق'); await p.waitForTimeout(400);
    await act('fav'); await shot('offer_fav');
    await p.click('#c-offer button:nth-child(2)'); await p.waitForTimeout(400);
    await sim('net', 'offline'); await act('reveal'); await shot('reveal_offline', 600); await tapText('إغلاق'); await p.waitForTimeout(400);
    await sim('net', 'online'); await sim('offer', 'last'); await act('expand'); await shot('offer_full_last', 600);
    await sim('offer', 'expired'); await shot('offer_full_expired');
    await sim('offer', 'used'); await shot('offer_full_used');
    await sim('offer', 'ok');
    await p.evaluate(() => { cfg.offer = 'o2c'; seg('c-offer', 'offer'); resetTo([{t: 'home'}, {t: 'merchant'}, {t: 'offer', mode: 'online', flow: 1}]); }); await p.waitForTimeout(400);
    await sim('offer', 'soon'); await shot('offer_o2c_online_soon');
    await sim('offer', 'ok');
    await p.evaluate(() => { resetTo([{t: 'home'}, {t: 'merchant'}, {t: 'offer', mode: 'full', flow: 1}]); }); await p.waitForTimeout(300);
    await act('policy'); await shot('o2c_policy', 600); await tapText('فهمت');
    await p.evaluate(() => { cfg.offer = 'o2a'; seg('c-offer', 'offer'); }); 
  });
  await run('scan', async () => {
    await p.evaluate(() => jump('r1')); await p.waitForTimeout(300);
    await sim('cam', 'ask'); await shot('cam_alert', 900);
    await tapText('عدم السماح'); await shot('cam_denied', 600);
    await tapText('أدخل رقم الفرع'); await shot('manual_empty', 600);
    for (const d of '111111') await p.keyboard.press(d);
    await shot('manual_wrong1', 300);
    await p.waitForTimeout(600);
    for (const d of '222222') await p.keyboard.press(d);
    await p.waitForTimeout(900);
    for (const d of '333333') await p.keyboard.press(d);
    await shot('manual_locked', 900);
    await p.evaluate(() => { top_().lock = 0; top_().tries = 0; rerenderAll(); }); await p.waitForTimeout(300);
    for (const d of '104233') await p.keyboard.press(d);
    await shot('manual_ok', 250); await shot('manual_to_r2', 1000);
    await p.evaluate(() => jump('r1')); await p.waitForTimeout(300);
    await sim('cam', 'ok');
    await ons('No QR in view'); await shot('scan_none_hint', 3200);
    await ons('Already counted'); await shot('scan_dup', 700);
    await tapText('اعرض الكود'); await shot('scan_dup_to_r2', 700);
    await p.evaluate(() => jump('r1')); await p.waitForTimeout(300);
    await ons('Server error'); await shot('scan_err', 700);
    await p.evaluate(() => { cfg.result = 'r2'; seg('c-result', 'result'); });
    await tapText('حاول مرة أخرى'); await shot('scan_err_retry', 3400);
    await p.evaluate(() => jump('r1')); await p.waitForTimeout(300);
    await sim('net', 'offline'); await shot('scan_offline', 300); await act('scanned'); await shot('scan_offline_f4', 600);
    await sim('net', 'online');
  });
  await run('r2', async () => {
    await p.evaluate(() => jump('r2')); await p.waitForTimeout(300);
    await ons('Code expired'); await shot('r2_expired');
    await tapText('أبلغ عن مشكلة'); await shot('report_pick', 600);
    await p.locator('#phone .rs button').nth(1).click(); await shot('report_picked', 200);
    await tapText('أرسل البلاغ'); await shot('report_sent', 300);
    await tapText('تم'); await p.waitForTimeout(400);
    await sim('net', 'offline'); await shot('r2_offline');
    await act('report'); await p.locator('#phone .rs button').nth(0).click(); await tapText('أرسل البلاغ'); await shot('report_queued', 300);
    await sim('net', 'online');
  });
  await run('h1', async () => {
    await p.evaluate(() => jump({t: 'h1'})); await p.waitForTimeout(300);
    await sim('user', 'new'); await shot('h1_new');
    await sim('user', 'regular');
    await ons('Older months fail'); await shot('h1_older_fail', 1400);
    await sim('net', 'online');
    await p.evaluate(() => jump('o2b_success')); await p.waitForTimeout(300);
    await act('onlineHelp'); await shot('online_help', 600);
  });
  await run('stores', async () => {
    await p.evaluate(() => jump({t: 'stores', lens: 's4'})); await p.waitForTimeout(300);
    await ons('No matches'); await shot('s4_empty');
    await p.evaluate(() => jump({t: 'stores', lens: 's6'})); await p.waitForTimeout(300);
    await ons('No matches'); await shot('s6_empty');
    await p.evaluate(() => jump({t: 'stores', lens: 's5'})); await p.waitForTimeout(300);
    await ons('No matches'); await shot('s5_empty');
    await act('favs'); await shot('favs', 600);
    await act('back'); await sim('user', 'new'); await act('favs'); await shot('favs_empty', 600);
    await sim('user', 'regular');
    await p.evaluate(() => jump({t: 'stores', lens: 's1'})); await sim('loc', 'off'); await shot('s3');
    await act('locOn'); await shot('s3_alert', 700); await tapText('السماح أثناء'); await shot('s3_after_allow', 600);
    await sim('net', 'offline'); await shot('s1_offline');
    await sim('net', 'online');
  });
  await p.screenshot({path: `${OUT}/zz_page.png`});
  console.log(errs.length ? errs.join('\n') : 'no console errors');
  await b.close();
})();
